-- 0038: TUMI — comprehensive GDPR/ethics-committee-aligned informed consent

UPDATE research_questionnaires
SET schema_json = '{"title":"TUMI Validation Study","description":"Tabletop User Motivation Inventory — validation study by NexLudica APS","showProgressBar":"top","progressBarType":"pages","showQuestionNumbers":"off","requiredText":"*","locale":"en","nx_shuffle_across_pages":true,"completedHtml":"<div style=\"padding:32px;text-align:center;\"><h2 style=\"color:#05abc4;\">Thank you!</h2><p>Your contribution helps validate the TUMI.</p></div>","pages":[{"name":"intro","title":"Welcome","elements":[{"type":"html","name":"intro_html","html":"<div style=\"background:#FFFFFF;padding:24px 28px;border-radius:10px;margin:4px 0 16px;box-shadow:0 1px 4px rgba(0,0,0,.06);line-height:1.65;color:#1b2528;\">\n  <h3 style=\"margin:0 0 16px;color:#05abc4;\">About this study</h3>\n  <p>In this study you will be asked to answer questions on board games.</p>\n  <p>If you ever played Monopoly or any other board game, card game, etc., think about that while you are compiling.</p>\n  <p style=\"margin-top:16px;color:#5c6b73;font-size:0.92em;\">Click <strong>Next</strong> to proceed to the informed consent.</p>\n</div>"}]},{"name":"consent","title":"Informed consent","elements":[{"type":"html","name":"consent_html","html":"<div style=\"background:#FFFFFF;padding:22px 26px;border-radius:10px;margin:4px 0 16px;box-shadow:0 1px 4px rgba(0,0,0,.06);line-height:1.55;color:#1b2528;\">\n\n  <h3 style=\"margin:0 0 10px;color:#05abc4;\">Participant Information Sheet & Informed Consent</h3>\n  <p style=\"margin:0 0 14px;color:#5c6b73;font-size:0.9em;\">Version 2.0 — Last updated: 26 May 2026</p>\n\n  <h4 style=\"margin:14px 0 6px;color:#1b2528;\">1. Study</h4>\n  <p style=\"margin:4px 0;\"><strong>Title:</strong> International validation of the Tabletop User Motivation Inventory (TUMI).</p>\n  <p style=\"margin:4px 0;\"><strong>Type:</strong> Online, cross-sectional, anonymous psychometric validation study.</p>\n  <p style=\"margin:4px 0;\"><strong>Estimated duration:</strong> 20–25 minutes.</p>\n  <p style=\"margin:4px 0;\"><strong>Funding:</strong> Conducted by NexLudica APS using internal resources; no external funding influences design, conduct, analysis, or publication.</p>\n\n  <h4 style=\"margin:14px 0 6px;color:#1b2528;\">2. Data Controller and Research Team</h4>\n  <p style=\"margin:4px 0;\"><strong>Data Controller (Titolare del trattamento):</strong></p>\n  <ul style=\"margin:4px 0 4px 22px;padding:0;\">\n    <li>NexLudica APS</li>\n    <li>Vico Barnabiti 10, 16124 Genova (GE), Italy</li>\n    <li>Italian Tax Code: 95252550108</li>\n    <li>Email: <a href=\"mailto:info@nexludica.org\" style=\"color:#05abc4;\">info@nexludica.org</a></li>\n  </ul>\n  <p style=\"margin:8px 0 4px;\"><strong>Principal Investigator:</strong> Vittorio Guerrieri — <a href=\"mailto:vittorio.guerrieri@nexludica.org\" style=\"color:#05abc4;\">vittorio.guerrieri@nexludica.org</a></p>\n  <p style=\"margin:4px 0;\">No Data Protection Officer is required under Art. 37 GDPR for this study. Data-protection enquiries can be sent to the Data Controller at the address above.</p>\n\n  <h4 style=\"margin:14px 0 6px;color:#1b2528;\">3. Purpose of the Study</h4>\n  <p style=\"margin:4px 0;\">To validate the psychometric properties (factor structure, internal consistency, construct validity) of the TUMI, a questionnaire measuring motivations underlying tabletop-gaming behaviour. Findings will contribute to peer-reviewed scientific literature on the psychology of play and tabletop gaming.</p>\n\n  <h4 style=\"margin:14px 0 6px;color:#1b2528;\">4. What You Will Be Asked to Do</h4>\n  <p style=\"margin:4px 0;\">After this consent page you will be asked:</p>\n  <ul style=\"margin:4px 0 4px 22px;padding:0;\">\n    <li>basic anonymous demographics (age range, gender, country of residence, first language);</li>\n    <li>brief questions about your relationship with tabletop games;</li>\n    <li>statements about your motivations to play, rated on a 1–7 Likert scale.</li>\n  </ul>\n  <p style=\"margin:8px 0 4px;\"><strong>Attention checks.</strong> Embedded among the statements you will find a small number of validated attention-check items drawn from the methodological literature (Curran &amp; Hauser, 2019). These items have transparently obvious correct answers (e.g., \"Oranges are fruit\") and are used to detect inattentive responding, in line with standard psychometric practice. Failing one or more attention checks may lead to your data being excluded from analyses but never to any other consequence.</p>\n\n  <h4 style=\"margin:14px 0 6px;color:#1b2528;\">5. Voluntary Participation and Right to Withdraw</h4>\n  <p style=\"margin:4px 0;\">Participation is entirely voluntary. You may:</p>\n  <ul style=\"margin:4px 0 4px 22px;padding:0;\">\n    <li>refuse to take part with no consequence;</li>\n    <li>withdraw at any time during the questionnaire by simply closing the browser tab — your incomplete responses will not be stored;</li>\n    <li>skip individual non-required items (only the consent items at the start are mandatory);</li>\n    <li>request deletion of your submitted data after completion (see Section 8).</li>\n  </ul>\n\n  <h4 style=\"margin:14px 0 6px;color:#1b2528;\">6. Risks, Benefits and Compensation</h4>\n  <p style=\"margin:4px 0;\"><strong>Risks:</strong> we anticipate no risks beyond those of everyday online activity. Some questions concern personal preferences and habits and may prompt reflection; if any item makes you uncomfortable, you may skip it or end the session.</p>\n  <p style=\"margin:4px 0;\"><strong>Benefits:</strong> you will not receive a direct personal benefit, but your contribution will advance scientific understanding of motivation in tabletop gaming.</p>\n  <p style=\"margin:4px 0;\"><strong>Compensation:</strong> if you were recruited through Prolific you will receive the compensation agreed on that platform upon submission of a valid response.</p>\n\n  <h4 style=\"margin:14px 0 6px;color:#1b2528;\">7. Personal Data and Legal Basis (Articles 6, 9 and 13 GDPR)</h4>\n  <p style=\"margin:4px 0;\"><strong>Data we collect:</strong></p>\n  <ul style=\"margin:4px 0 4px 22px;padding:0;\">\n    <li>your answers to the questionnaire (demographics + Likert ratings);</li>\n    <li>your Prolific participant ID (a pseudonym managed by Prolific Academic Ltd.), if you arrive through that platform — used only to credit your compensation and to prevent duplicate submissions;</li>\n    <li>a non-identifying SHA-256 hash of your IP address, kept solely for anti-spam protection;</li>\n    <li>technical metadata: timestamp, user-agent string, presentation order of items (deterministic seed for methodological analyses).</li>\n  </ul>\n  <p style=\"margin:8px 0 4px;\">We do <strong>not</strong> collect your name, surname, email, postal address, date of birth, IP address in plain form, or any direct identifier. We do not collect special categories of personal data within the meaning of Art. 9 GDPR.</p>\n  <p style=\"margin:8px 0 4px;\"><strong>Legal basis:</strong></p>\n  <ul style=\"margin:4px 0 4px 22px;padding:0;\">\n    <li>Art. 6(1)(a) GDPR — your explicit, freely given, informed and unambiguous consent;</li>\n    <li>Art. 89(1) GDPR — processing for scientific research purposes with appropriate safeguards (data minimisation, pseudonymisation, no decisions about individuals).</li>\n  </ul>\n\n  <h4 style=\"margin:14px 0 6px;color:#1b2528;\">8. Data Storage, Retention and Sharing</h4>\n  <p style=\"margin:4px 0;\"><strong>Storage:</strong> data are stored on Cloudflare D1 servers located in the European Union (Milan, Italy). Access is restricted to the research team and protected by authentication.</p>\n  <p style=\"margin:4px 0;\"><strong>Retention:</strong> identifiable pseudonymous data (including the Prolific ID) are retained for up to 24 months after the close of data collection, then either fully anonymised (Prolific ID irreversibly removed) or deleted. Fully anonymised, aggregate data may be retained indefinitely.</p>\n  <p style=\"margin:4px 0;\"><strong>Sharing and publication:</strong> findings will be published in peer-reviewed venues, conferences and open-science repositories, always in aggregate form. A fully anonymised dataset (with Prolific IDs removed) may be deposited in a public scientific repository (e.g., OSF, Zenodo) to support open science and replicability, in accordance with the FAIR data principles.</p>\n  <p style=\"margin:4px 0;\"><strong>Transfers outside the EU:</strong> Cloudflare, Inc. is a US-based provider with EU data-residency guarantees; any incidental transfer occurs under the EU Standard Contractual Clauses (Art. 46 GDPR).</p>\n\n  <h4 style=\"margin:14px 0 6px;color:#1b2528;\">9. Your Rights (Articles 15–22 GDPR)</h4>\n  <p style=\"margin:4px 0;\">You have the right to: (a) access your personal data and obtain a copy; (b) rectify inaccurate data; (c) request erasure (\"right to be forgotten\"); (d) restrict processing; (e) data portability; (f) object to processing; (g) withdraw your consent at any time, without affecting the lawfulness of processing prior to withdrawal.</p>\n  <p style=\"margin:4px 0;\">To exercise these rights, please contact the Data Controller at <a href=\"mailto:info@nexludica.org\" style=\"color:#05abc4;\">info@nexludica.org</a> quoting your Prolific ID (or the completion code shown at the end of the survey) so we can locate your record. Requests will be answered within 30 days.</p>\n  <p style=\"margin:4px 0;\">You also have the right to lodge a complaint with the Italian Data Protection Authority (Garante per la protezione dei dati personali, <a href=\"https://www.garanteprivacy.it\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#05abc4;\">www.garanteprivacy.it</a>) or with the supervisory authority of your country of residence within the EU.</p>\n\n  <h4 style=\"margin:14px 0 6px;color:#1b2528;\">10. Ethical Standards</h4>\n  <p style=\"margin:4px 0;\">This study has been designed in accordance with: (i) the World Medical Association''s Declaration of Helsinki (as revised in 2013); (ii) the Code of Human Research Ethics of the British Psychological Society (2021); (iii) Regulation (EU) 2016/679 (GDPR) and the Italian Personal Data Protection Code (D.Lgs. 196/2003 as amended by D.Lgs. 101/2018); (iv) the EU Code of Conduct for Research Integrity (ALLEA, 2023). No automated decision-making (including profiling) under Art. 22 GDPR is performed on your data.</p>\n\n  <h4 style=\"margin:14px 0 6px;color:#1b2528;\">11. Eligibility</h4>\n  <p style=\"margin:4px 0;\">To take part you must be at least <strong>18 years old</strong> and able to read and understand English.</p>\n\n  <h4 style=\"margin:14px 0 6px;color:#1b2528;\">12. Consent</h4>\n  <p style=\"margin:4px 0;\">Please indicate your agreement to both items below. Without explicit \"Yes\" to both you will not be able to proceed.</p>\n\n</div>"},{"type":"boolean","name":"consent_age","title":"I confirm that I am at least 18 years old.","isRequired":true,"labelTrue":"Yes","labelFalse":"No","validators":[{"type":"expression","expression":"{consent_age} = true","text":"You must be at least 18 to take part."}]},{"type":"boolean","name":"consent_data","title":"I have read and understood the Participant Information Sheet above, I have had the opportunity to ask questions, and I freely consent to participate in this study and to the processing of my data as described.","isRequired":true,"labelTrue":"Yes","labelFalse":"No","validators":[{"type":"expression","expression":"{consent_data} = true","text":"Consent is required to proceed."}]}]},{"name":"demographics","title":"About you","description":"A few basic anonymous questions to help us analyse the data.","elements":[{"type":"text","name":"age","title":"Age","isRequired":true,"inputType":"number","min":18,"max":99},{"type":"radiogroup","name":"gender","title":"Gender","isRequired":true,"choices":[{"value":"f","text":"Female"},{"value":"m","text":"Male"},{"value":"nb","text":"Non-binary / other"},{"value":"na","text":"Prefer not to say"}]},{"type":"text","name":"country","title":"Country of residence","isRequired":true,"placeholder":"e.g. Italy, USA, …"},{"type":"text","name":"first_language","title":"First language","isRequired":true,"placeholder":"e.g. English, Italian, …"}]},{"name":"player_profile","title":"Your relationship with board games","description":"These questions help us understand how strongly you identify as a board gamer. There are no right or wrong answers — we expect a wide range of profiles.","elements":[{"type":"rating","name":"bg_liking","title":"Overall, how much do you like board games?","isRequired":true,"rateMin":1,"rateMax":10,"minRateDescription":"Not at all","maxRateDescription":"Love them"},{"type":"matrix","name":"bg_proxy","title":"How much do you agree with each statement?","isAllRowRequired":true,"columns":[{"value":1,"text":"1\nStrongly disagree"},{"value":2,"text":"2"},{"value":3,"text":"3"},{"value":4,"text":"4\nNeutral"},{"value":5,"text":"5"},{"value":6,"text":"6"},{"value":7,"text":"7\nStrongly agree"}],"rows":[{"value":"bg_p1","text":"In the past year I have bought at least one board game."},{"value":"bg_p2","text":"I currently own more than 10 board games."},{"value":"bg_p3","text":"In the past month I have played a board game at least once."},{"value":"bg_p4","text":"I follow content creators (YouTubers, podcasts, blogs) about board games."}]},{"type":"radiogroup","name":"bg_expertise","title":"How would you describe your experience with board games?","isRequired":true,"choices":[{"value":"novice","text":"Novice — I rarely play, mostly party / family classics"},{"value":"casual","text":"Casual — I play occasionally, I know a few modern games"},{"value":"regular","text":"Regular — I play frequently and know many modern games"},{"value":"enthusiast","text":"Enthusiast — board games are a serious hobby of mine"},{"value":"expert","text":"Expert — I design, review, or actively follow the industry"}]}]},{"name":"tumi_1","title":"Section 1 of 6","description":"For each statement, indicate how much you agree on a 1–7 scale. Order is randomised for your session.","elements":[{"type":"matrix","name":"tumi_matrix_1","title":"How much do you agree with each statement?","isAllRowRequired":false,"columns":[{"value":1,"text":"1\nStrongly disagree"},{"value":2,"text":"2"},{"value":3,"text":"3"},{"value":4,"text":"4\nNeutral"},{"value":5,"text":"5"},{"value":6,"text":"6"},{"value":7,"text":"7\nStrongly agree"}],"rows":[{"value":"CO04","text":"I track my win rates and strive to improve them."},{"value":"SO14","text":"Small talk during games distracts me more than it entertains."},{"value":"ID12","text":"I like it when I have the freedom to invent a story within a game"},{"value":"MA11","text":"I find it very rewarding to improve at a board game"},{"value":"PO09","text":"I like to collect games"},{"value":"SO05","text":"I like teaching board games"},{"value":"CO09","text":"I feel uncomfortable when games become too competitive."},{"value":"FO10","text":"Seeing other people talk about a game I don''t know makes me want to try it."},{"value":"FA15","text":"Stories in board games are just getting in the way"},{"value":"ID11","text":"I like games that allow me to tell my story"},{"value":"PR14","text":"It embarrasses me to point out that I get bored at a board game"},{"value":"ES10","text":"I like playing board games because they allow me to escape from real life."},{"value":"ES07","text":"I play games for entertainment rather than emotional relief."},{"value":"CU04","text":"I like building board game accessories"},{"value":"AE04","text":"The material of the game components is irrelevant"},{"value":"NO10","text":"I don''t have any game a play often because I find them comforting"},{"value":"AN01","text":"I’d miss the clatter of dice and shuffling if everything were digital."},{"value":"PR12","text":"If I don''t play certain games it would be hard for me to keep some friendships"},{"value":"SM05","text":"I avoid games that hinge on bluffing"},{"value":"AR08","text":"I dislike games with time pressure."},{"value":"NO09","text":"Replaying certain games gives me comfort"},{"value":"SO02","text":"I like to chat with other players"},{"value":"BG02","text":"I have never used a computer."},{"value":"PR02","text":"I play so as not to risk being excluded from my group of friends"},{"value":"RE04","text":"I see game nights as opportunities to strengthen relationships."},{"value":"CO18","text":"I like to beat others"},{"value":"AN06","text":"The physical bits don’t add much; the rules are what matter."},{"value":"MA14","text":"I like it if a game realistically simulates a fact of reality"},{"value":"TE09","text":"I find coordinating with others more frustrating than fun."},{"value":"PO15","text":"I want to own as many games as possible so I can play in more situations."},{"value":"SM09","text":"I like games where deals decide the outcome."},{"value":"BG06","text":"Oranges are fruit."},{"value":"GD11","text":"I evaluate how component design supports smooth play."},{"value":"SM14","text":"I like it when there are secrets among players"},{"value":"FA03","text":"I like to customize my character if the game allows it"},{"value":"FA16","text":"I like that the game world is detailed"},{"value":"SO13","text":"I prefer focused, quiet tables with minimal side chatter."},{"value":"FO02","text":"Limited editions tempt me even when I don’t need them."},{"value":"FO04","text":"New releases come and go; I barely notice."},{"value":"PR07","text":"If I don’t want to play, I simply don’t—no guilt attached."},{"value":"PR06","text":"I worry about being excluded if I don''t join gaming sessions."},{"value":"CO13","text":"Losing a game always makes me upset"},{"value":"FO11","text":"If there''s a lot of talk about a board game, it makes me want to try it."}]}]},{"name":"tumi_2","title":"Section 2 of 6","description":"Continue indicating how much you agree with each statement.","elements":[{"type":"matrix","name":"tumi_matrix_2","title":"How much do you agree with each statement?","isAllRowRequired":false,"columns":[{"value":1,"text":"1\nStrongly disagree"},{"value":2,"text":"2"},{"value":3,"text":"3"},{"value":4,"text":"4\nNeutral"},{"value":5,"text":"5"},{"value":6,"text":"6"},{"value":7,"text":"7\nStrongly agree"}],"rows":[{"value":"FO08","text":"I worry about missing out on limited or exclusive editions."},{"value":"ID05","text":"I usually just play as “myself,” not as a character"},{"value":"AR09","text":"I seek out games that create tension and suspense."},{"value":"SO04","text":"I often frequent environments where board games are played."},{"value":"FO03","text":"I need to play the latest games to stay current."},{"value":"SO15","text":"I find excessive table talk distracting."},{"value":"PR10","text":"It often happens that I play because my friends ask me to."},{"value":"AR04","text":"I find that playing board games increases my adrenaline"},{"value":"GD13","text":"The design behind a board game matters little to me."},{"value":"SM10","text":"Outmaneuvering people through negotiation is fun for me."},{"value":"PO03","text":"I like to look for good deals regarding board games."},{"value":"ID04","text":"I find myself speaking in character during role-playing games."},{"value":"ES15","text":"I use gaming to relax after a stressful day."},{"value":"RE06","text":"I keep my gaming life separate from my personal relationships."},{"value":"FO09","text":"I feel anxious when I hear about popular games I haven''t tried."},{"value":"GD05","text":"I like to discuss design choices of games"},{"value":"MA12","text":"I feel proud when I master an aspect of a board game"},{"value":"AR11","text":"I like the excitement of not knowing what is about to happen."},{"value":"AE03","text":"I appreciate the tactile pleasure of high-quality game pieces."},{"value":"CU06","text":"I enjoy making games uniquely mine through modifications."},{"value":"CO02","text":"I play games with the primary goal of winning."},{"value":"CO15","text":"I like to be known as someone good at certain games"},{"value":"PO01","text":"I like acquiring titles even if I’m not sure when I’ll play them."},{"value":"SM06","text":"I like games where deception decide the outcome"},{"value":"CO07","text":"I don''t mind losing as long as everyone has fun."},{"value":"AE09","text":"Artwork is irrelevant to me; function is all that matters."},{"value":"PR13","text":"Sometimes I happen to play even if I don''t feel like it."},{"value":"RE12","text":"I want to form meaningful friendships with the people I play board games with."},{"value":"BG01","text":"I work fourteen months in a year."},{"value":"NO11","text":"Some games I like because an important person in my life taught them to me"},{"value":"RE07","text":"I don''t expect games to affect my friendships."},{"value":"ID10","text":"If I don''t identify with a character, I don''t have fun."},{"value":"GD02","text":"I like to \"break\" the games rules"},{"value":"CU10","text":"I find painting miniatures to be boring."},{"value":"ID07","text":"I avoid roleplay"},{"value":"RE05","text":"Once the game ends, I’m not looking to connect further."},{"value":"GD04","text":"I don''t like to explore different ways to bend the rules"},{"value":"MA01","text":"I like drilling into game systems until I truly understand them."},{"value":"SO16","text":"I would enjoy games just as much played in silence."},{"value":"PR03","text":"I sometimes join games mainly because others expect me to."},{"value":"MA20","text":"I get frustrated when randomness removes my ability to plan."},{"value":"PO16","text":"I like owning the right game for every situation"},{"value":"TE02","text":"It''s also important for me to be able to support other players."}]}]},{"name":"tumi_3","title":"Section 3 of 6","description":"Continue indicating how much you agree with each statement.","elements":[{"type":"matrix","name":"tumi_matrix_3","title":"How much do you agree with each statement?","isAllRowRequired":false,"columns":[{"value":1,"text":"1\nStrongly disagree"},{"value":2,"text":"2"},{"value":3,"text":"3"},{"value":4,"text":"4\nNeutral"},{"value":5,"text":"5"},{"value":6,"text":"6"},{"value":7,"text":"7\nStrongly agree"}],"rows":[{"value":"PO12","text":"I see no value in owning games I rarely play."},{"value":"FA09","text":"I follow the plot as if I’m living inside it."},{"value":"PO13","text":"A big collection doesn’t interest me; access is enough."},{"value":"ES14","text":"When I play, I lose track of time."},{"value":"PO06","text":"I sometimes avoid bringing around certain games I really care about"},{"value":"FA14","text":"Board game stories are important to me"},{"value":"ES02","text":"Playing helps me switch off worries I can’t shake otherwise."},{"value":"MA18","text":"I like to improve as a player over time"},{"value":"ES04","text":"I find games help me manage difficult emotions."},{"value":"SM11","text":"I dislike having to make deals during a game"},{"value":"ES05","text":"I rarely play to distract myself from how I’m feeling."},{"value":"CO05","text":"I don''t surrender easily"},{"value":"SM08","text":"I prefer games where all information is open and honest."},{"value":"CU09","text":"I stick to official pieces without changes."},{"value":"MA07","text":"I’m fine playing sloppily if it keeps things moving."},{"value":"MA17","text":"I like games with great strategic depth"},{"value":"FO05","text":"I''m content playing old games."},{"value":"TE03","text":"I like to help other players"},{"value":"CO17","text":"The most fun part is the head-to-head comparison with opponents."},{"value":"CU02","text":"I like to improve the pieces of my board games"},{"value":"NO04","text":"I don’t cling to “classics” just because they’re classics."},{"value":"CU11","text":"I like game that involve crafting something new"},{"value":"ES11","text":"I like to imagine a better version of my life in board games"},{"value":"CO19","text":"I like to do better than other players"},{"value":"AE10","text":"I find elaborate game art to be an unnecessary expense."},{"value":"RE02","text":"I like lasting friendships through gaming groups."},{"value":"CO01","text":"Outplaying others gives me a real thrill."},{"value":"AN03","text":"I’d be just as happy playing a digital version of most games."},{"value":"AN04","text":"Physical stuff in games don’t affect my enjoyment."},{"value":"NO08","text":"I don''t like to play traditional games"},{"value":"NO02","text":"Familiar titles comfort me because of old memories."},{"value":"RE01","text":"I use game nights to deepen friendships outside the game."},{"value":"AE05","text":"I''m drawn to games with beautiful artwork and components."},{"value":"SO09","text":"Table talk and jokes are a big part of why I play."},{"value":"CO03","text":"I study rules to win more often"},{"value":"NO03","text":"My past gaming history has little to do with what I play now."},{"value":"PO05","text":"I don''t care if my games get worn out with use"},{"value":"SM01","text":"I don''t enjoy games where I have to ally myself with other players"},{"value":"AN07","text":"The tactile feel of cards, dice, and miniatures is a big draw for me."},{"value":"CU03","text":"I like board games that involve customization, such as painting miniatures."},{"value":"AN02","text":"I find digital implementations lose something essential."},{"value":"BG03","text":"I am paid biweekly by leprechauns."},{"value":"RE10","text":"I like it if my board game friends offer me support when I have a real-life problem"}]}]},{"name":"tumi_4","title":"Section 4 of 6","description":"Continue indicating how much you agree with each statement.","elements":[{"type":"matrix","name":"tumi_matrix_4","title":"How much do you agree with each statement?","isAllRowRequired":false,"columns":[{"value":1,"text":"1\nStrongly disagree"},{"value":2,"text":"2"},{"value":3,"text":"3"},{"value":4,"text":"4\nNeutral"},{"value":5,"text":"5"},{"value":6,"text":"6"},{"value":7,"text":"7\nStrongly agree"}],"rows":[{"value":"ID02","text":"I dedicate a lot of care to character creation, when the game allows it."},{"value":"FA05","text":"Getting lost in a game’s story is an important part for me."},{"value":"MA06","text":"I prefer simple games that don''t require complex thinking"},{"value":"TE01","text":"I prefer to play in a team rather than alone"},{"value":"ID03","text":"I enjoy making decisions as if I were actually my character."},{"value":"PR05","text":"I sometimes keep playing a campaign because quitting would feel rude."},{"value":"CU05","text":"Painting minis or customising components is part of the fun for me."},{"value":"AR02","text":"I enjoy the adrenaline rush of high-stakes moments."},{"value":"TE10","text":"Group strategy talk feels like a chore, not a perk."},{"value":"ES01","text":"I use gaming sessions to decompress from daily stress."},{"value":"MA03","text":"I feel satisfied when I fully understand a game''s systems."},{"value":"FO07","text":"I ignore gaming trends and hype."},{"value":"MA05","text":"Learning every nuance of a game feels like overkill to me."},{"value":"MA08","text":"Deep strategy talk bores me quickly."},{"value":"CO12","text":"Losing is not fun"},{"value":"MA02","text":"I enjoy discovering optimal strategies"},{"value":"RE08","text":"I would play just as happily with people I will never meet again"},{"value":"SO11","text":"I like games that encourage table talk and interaction."},{"value":"FO01","text":"I feel the urge to try the latest hot release right away."},{"value":"ES16","text":"Playing improves my mood when I feel down."},{"value":"FA12","text":"I skip through story elements to get to the gameplay."},{"value":"SM02","text":"I like it when alliances are formed between players"},{"value":"CO10","text":"Competing against others feels more stressful than fun."},{"value":"ID08","text":"I like games where I can play a character."},{"value":"FA10","text":"I find myself thinking about game narratives long after playing."},{"value":"PO14","text":"Playing a game I own is more satisfying than playing a borrowed one."},{"value":"ES03","text":"I use long sessions when I need a mental break from my problems"},{"value":"CU01","text":"I like to embellish my board games"},{"value":"TE04","text":"I like to play board games collaboratively"},{"value":"ES12","text":"When I play board games, I think less about my problems."},{"value":"CU08","text":"I see no point in customizing game components."},{"value":"AR03","text":"I play board games because they excite me"},{"value":"SM03","text":"I find games with betrayal exciting."},{"value":"FA02","text":"I look forward to finding out what''s going to happen in the story of a board game."},{"value":"NO06","text":"I play some games because they remind me of happy moments from my past"},{"value":"ES09","text":"I like playing board games because they allow me to distract myself from my problems"},{"value":"RE09","text":"I enjoy talking about my personal problems with my board game companions."},{"value":"SO08","text":"Playing board games is part of a routine with my friends"},{"value":"NO07","text":"Playing certain games is a beautiful tradition"},{"value":"PO02","text":"Buying games I won’t use feels pointless to me."},{"value":"FA08","text":"I like to \"lose myself\" in a story while playing."},{"value":"SO06","text":"I like games because they make social interactions more pleasant"},{"value":"RE11","text":"I enjoy having important and deep conversations with other players."}]}]},{"name":"tumi_5","title":"Section 5 of 6","description":"Continue indicating how much you agree with each statement.","elements":[{"type":"matrix","name":"tumi_matrix_5","title":"How much do you agree with each statement?","isAllRowRequired":false,"columns":[{"value":1,"text":"1\nStrongly disagree"},{"value":2,"text":"2"},{"value":3,"text":"3"},{"value":4,"text":"4\nNeutral"},{"value":5,"text":"5"},{"value":6,"text":"6"},{"value":7,"text":"7\nStrongly agree"}],"rows":[{"value":"CO20","text":"Being in a ranking motivates me to play"},{"value":"AE08","text":"Fancy visuals don’t affect whether I like a game."},{"value":"SO12","text":"I like sessions where conversation flows constantly."},{"value":"NO05","text":"I prefer discovering new games over revisiting old ones."},{"value":"MA16","text":"I like simple games"},{"value":"CO06","text":"I shy away from direct competition"},{"value":"MA19","text":"I like finding clever solutions to problems"},{"value":"MA13","text":"I like understanding complex mechanics"},{"value":"RE03","text":"I’m happy when a session leads to plans or chats afterward."},{"value":"GD06","text":"I enjoy thinking about how a board game’s mechanics shape player decisions."},{"value":"MA10","text":"I like to think of all possible strategies when I play board games."},{"value":"SO10","text":"I enjoy playful banter even when it’s not about the game."},{"value":"GD12","text":"I rarely think about why a board game works; I just play."},{"value":"FA06","text":"I like to do things I couldn''t do in real life through board games"},{"value":"AE06","text":"Gorgeous components can win me over even before I know the rules."},{"value":"ES06","text":"I feel like playing games only when I''m mentally in a good place"},{"value":"BG04","text":"I have been to every country in the world."},{"value":"SM04","text":"I enjoy bluffing games."},{"value":"SO07","text":"I like to have shared experiences playing that I can talk about later."},{"value":"AR05","text":"Playing board games gives me a lot of energy"},{"value":"FO06","text":"I don''t care if I miss out on new releases."},{"value":"AN11","text":"I like the digital versions of the board game"},{"value":"AE02","text":"I barely notice component quality once we start playing."},{"value":"PR01","text":"I don''t need to play games to keep my friendships"},{"value":"ID06","text":"Adopting a character’s viewpoint feels forced to me."},{"value":"AR01","text":"My heart rate jumps in suspenseful turns—and I love it."},{"value":"AN10","text":"I like that board games are played in person"},{"value":"NO01","text":"I keep playing games that hold special memories for me."},{"value":"PR09","text":"I never feel pressured to participate in games."},{"value":"PR08","text":"Group pressure doesn’t influence my decision to join."},{"value":"MA15","text":"I like it if I have to think a lot about the strategies to put into a game"},{"value":"CO16","text":"I like to play to show my friends how good I am"},{"value":"ES13","text":"When I play board games, I experience fewer negative emotions"},{"value":"CO08","text":"I don’t chase optimal moves; I just go with the flow."},{"value":"AR06","text":"I prefer calm, relaxing games without pressure."},{"value":"PO10","text":"Adding a new game to my library excites me"},{"value":"MA09","text":"I like to understand all aspects of a board game I''m playing"},{"value":"PO07","text":"Owning shelves of games is rewarding in itself."},{"value":"AR10","text":"Board games keep me on the edge of my seat"},{"value":"FA11","text":"Without a rich narrative, a game feels thin to me."},{"value":"ES18","text":"I like feeling in control while playing"},{"value":"SM12","text":"I like games where you have to negotiate with other players"},{"value":"PO11","text":"I don’t care who owns the game as long as I can play."}]}]},{"name":"tumi_6","title":"Section 6 of 6","description":"Continue indicating how much you agree with each statement.","elements":[{"type":"matrix","name":"tumi_matrix_6","title":"How much do you agree with each statement?","isAllRowRequired":false,"columns":[{"value":1,"text":"1\nStrongly disagree"},{"value":2,"text":"2"},{"value":3,"text":"3"},{"value":4,"text":"4\nNeutral"},{"value":5,"text":"5"},{"value":6,"text":"6"},{"value":7,"text":"7\nStrongly agree"}],"rows":[{"value":"AE07","text":"Visual appeal is an important part of why I choose to play games"},{"value":"SM13","text":"I find games with secret roles exciting."},{"value":"SO03","text":"The atmosphere created among the players is important to me."},{"value":"MA04","text":"I enjoy optimizing turns even when no one else is watching."},{"value":"GD09","text":"I often propose house rules to test alternative design ideas."},{"value":"TE06","text":"Cooperative victories feel better than solo wins."},{"value":"ES08","text":"When I''m stressed out, I''m not in the mood for playing"},{"value":"NO12","text":"Who teaches me a game is irrelevant to the attachement I have to the game"},{"value":"SO01","text":"I like meeting other players"},{"value":"AN05","text":"I prefer digital games for their convenience and automation."},{"value":"AN09","text":"I experience board games as a break from screens"},{"value":"GD07","text":"I pay attention to how small rule changes could improve a board game."},{"value":"GD03","text":"I like to push the rules of a game to the limit"},{"value":"PO04","text":"I am careful not to ruin my games."},{"value":"AE01","text":"The color, shape, and feel of board game pieces are important to me"},{"value":"PR04","text":"I sometimes play games to avoid disappointing others."},{"value":"PR11","text":"I don''t want to disappoint people who expect me to play."},{"value":"FA07","text":"I like the thrill of taking on an alter ego in a game"},{"value":"SM07","text":"I dislike games that require lying or deceiving others."},{"value":"TE05","text":"Coordinating with others toward a joint win is satisfying."},{"value":"FA04","text":"I like when I can develop my character in the games"},{"value":"AN08","text":"Handling physical components makes the experience real for me."},{"value":"TE07","text":"I enjoy synchronizing actions with others."},{"value":"CO14","text":"For me, it''s important to be the best person at playing."},{"value":"ES17","text":"Playing improves my mood"},{"value":"GD14","text":"I am not interested in how rules work during play."},{"value":"GD01","text":"I like to discover new and inventive game designs"},{"value":"TE08","text":"I prefer having complete responsability over my own success."},{"value":"CU07","text":"I take pride in personalizing my gaming accessories."},{"value":"GD10","text":"The fit between theme and mechanics is a major reason I want to play a board game."},{"value":"AR07","text":"I avoid games that make me feel anxious or stressed."},{"value":"FA13","text":"I don’t need lore or worldbuilding to enjoy a session"},{"value":"PO08","text":"I take pride in my game collection''s size and variety."},{"value":"CO11","text":"Winning is important to me"},{"value":"ID09","text":"I like the thrill of pretending to be someone else"},{"value":"ID01","text":"I like exploring how my character would think and feel."},{"value":"BG05","text":"I have the power to cast spells on others."},{"value":"FA01","text":"Narrative twists rarely grab my attention."},{"value":"GD08","text":"Understanding the balance between luck and skill in a design motivates me to play."}]}]}]}',
    version = version + 1,
    updated_at = unixepoch()
WHERE id = '00000000-0000-4000-8000-300000000010';
